namespace NotificationApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications;
    private int _nextId;

    public NotificationService()
    {
        _notifications =
        [
            new(1, "Welcome to NotificationApp!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
            new(3, "New feature: real-time polling!", DateTime.UtcNow.AddMinutes(-5)),
        ];
        _nextId = 4;
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>
    /// Returns notifications added after the given timestamp.
    /// Randomly generates a new notification ~30% of the time to simulate activity.
    /// </summary>
    public Task<List<Notification>> GetNewNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            if (Random.Shared.NextDouble() < 0.3)
            {
                var id = _nextId++;
                _notifications.Add(new Notification(
                    id,
                    $"New event #{id} just happened.",
                    DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications
                    .Where(n => n.Timestamp > since)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

