@code {
    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    private List<Notification> notifications = [];
    private DateTime lastCheck = DateTime.MinValue;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Interactive render: state was restored from prerender — skip the fetch.
            notifications = PersistedNotifications;
        }
        else
        {
            // Prerender: load initial data and persist it for the interactive handoff.
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }

        if (notifications.Count > 0)
        {
            lastCheck = notifications.Max(n => n.Timestamp);
        }
        else
        {
            lastCheck = DateTime.UtcNow;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender, so the polling
        // loop only starts once the page is live and interactive.
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                var newOnes = await NotificationService.GetNewNotificationsSinceAsync(lastCheck);
                if (newOnes.Count > 0)
                {
                    notifications.InsertRange(0, newOnes);
                    lastCheck = newOnes.Max(n => n.Timestamp);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on disposal — exit cleanly.
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

